<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth';import {api} from '../api';import {journeyFor} from '../customerLanguage';import {Plus,Search,ArrowUpRight,FileText,Building2,Calculator,FolderOpen} from 'lucide-vue-next';
const auth=useAuth(),router=useRouter(),files=ref<any[]>([]),borrowers=ref<any[]>([]),error=ref(''),busy=ref(false),creating=ref(false),query=ref(''),filter=ref('all');const form=ref({name:'',reference:'',borrower_id:'',module:'bank',is_demo:false,new_borrower:''});const editable=computed(()=>['owner','admin','underwriter','processor'].includes(auth.membership?.role));const visible=computed(()=>files.value.filter(f=>filter.value==='all'||(filter.value==='archived'?!!f.archived_at:!f.archived_at&&f.module===filter.value)));
const moduleName=(m:string)=>m==='bank'?'Bank statements':m==='dscr'?'Rental income':'Appraisal';
const rank:Record<string,number>={upload:0,start:1,failed:2,review:3,processing:4,export:5,archived:6};
function fileJourney(f:any){return journeyFor({documents:f.progress?.documents??0,runStatus:f.progress?.run_status??null,hasReport:!!f.progress?.has_report,archived:!!f.archived_at,fileStatus:f.status,module:f.module})}
const nextFile=computed(()=>{const ranked=files.value.filter(f=>!f.archived_at).map(f=>({f,j:journeyFor({documents:f.progress?.documents??0,runStatus:f.progress?.run_status??null,hasReport:!!f.progress?.has_report,fileStatus:f.status,module:f.module})}));ranked.sort((a,b)=>(rank[a.j.phase]??9)-(rank[b.j.phase]??9));return ranked[0]||null});
async function load(){try{busy.value=true;files.value=(await api('/api/files?organization_id='+auth.orgId+'&q='+encodeURIComponent(query.value))).data;borrowers.value=await api('/api/organizations/'+auth.orgId+'/borrowers')}catch(e:any){error.value=e.message}finally{busy.value=false}}onMounted(load);
async function create(){busy.value=true;error.value='';try{let id=Number(form.value.borrower_id);if(form.value.new_borrower)id=(await api('/api/organizations/'+auth.orgId+'/borrowers','POST',{name:form.value.new_borrower})).id;const f=await api('/api/organizations/'+auth.orgId+'/files','POST',{...form.value,borrower_id:id});router.push('/files/'+f.id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template>
<section>
<div class="page-heading"><div><span class="eyebrow">Loan files</span><h1>{{files.length?'Your loan files':'Start with one loan file'}}</h1><p class="muted">Each file is one borrower. Upload statements, review what was flagged, then export a report.</p></div><button v-if="editable" class="primary" @click="creating=true"><Plus :size="18"/>{{files.length?'New loan file':'Create your first loan file'}}</button></div>
<div class="notice"><span class="badge teal">A person decides</span><div><strong>The tool only flags potential issues.</strong><p>It does not approve or decline a loan, and it does not decide that something is fraud.</p></div></div>
<article v-if="nextFile" class="next-step-card"><p class="eyebrow">Do this next</p><h2>{{nextFile.j.title}}</h2><p><strong>{{nextFile.f.name}}</strong> · {{nextFile.j.body}}</p><RouterLink class="button primary" :to="'/files/'+nextFile.f.id">{{nextFile.j.cta||'Open this file'}}</RouterLink></article>
<div class="stat-grid"><article class="stat"><span>Loan files you can open</span><strong>{{files.length}}</strong><small>Only files shared with you</small></article><article class="stat"><span>In review</span><strong>{{files.filter(f=>!f.archived_at&&fileJourney(f).phase==='review').length}}</strong><small>Someone is checking findings</small></article><article class="stat"><span>Practice files</span><strong>{{files.filter(f=>f.is_demo).length}}</strong><small>Fictional samples, kept separate</small></article></div>
<div class="module-grid"><article v-for="m in [{id:'bank',name:'Bank statements',icon:FileText,text:'Deposits, transfers, and NSF items over 12 or 24 months.'},{id:'appraisal',name:'Appraisal',icon:Building2,text:'The property report, photos, and items to check.'},{id:'dscr',name:'Rental income',icon:Calculator,text:'Rent divided by the monthly payment (DSCR).'}]" class="module-card"><component :is="m.icon" :size="25"/><h3>{{m.name}}</h3><p>{{m.text}}</p><button class="text-button" @click="filter=m.id">Show these files <ArrowUpRight :size="16"/></button></article></div>
<div class="section-heading"><h2>All files</h2><form class="search" @submit.prevent="load"><Search :size="17"/><input aria-label="Search loan files" v-model="query" placeholder="Search by file name"/><button>Search</button></form></div>
<div class="tabs" role="tablist" aria-label="Filter loan files"><button v-for="[id,label] in [['all','All files'],['bank','Bank statements'],['appraisal','Appraisals'],['dscr','Rental income'],['archived','Archived']]" :key="id" role="tab" :aria-selected="filter===id" :class="{active:filter===id}" @click="filter=id">{{label}}</button></div>
<p class="alert error" role="alert" v-if="error">{{error}}</p>
<div class="table-wrap"><table><thead><tr><th>Loan file</th><th>What it reviews</th><th>Status</th><th>Kind of file</th><th><span class="sr-only">Open</span></th></tr></thead><tbody><tr v-for="file in visible" :key="file.id"><td><RouterLink :to="'/files/'+file.id" class="file-link">{{file.name}}</RouterLink><small>{{file.borrower?.name}}<template v-if="file.reference"> · {{file.reference}}</template></small></td><td>{{moduleName(file.module)}}</td><td><span class="badge" :class="fileJourney(file).badge.tone">{{fileJourney(file).badge.label}}</span></td><td><span :class="['badge',file.is_demo?'amber':'teal']">{{file.is_demo?'Practice file':'Your documents'}}</span></td><td><RouterLink class="button" :to="'/files/'+file.id">Open</RouterLink></td></tr></tbody></table>
<div class="empty-state" v-if="!busy&&!files.length"><FolderOpen :size="40"/><h3>Create your first loan file</h3><p>Name the file and the borrower. The next step on that page is <strong>Upload bank statements</strong>.</p><button v-if="editable" class="primary" @click="creating=true">Create your first loan file</button></div>
<div class="empty-state" v-else-if="!busy&&!visible.length"><FolderOpen :size="40"/><h3>Nothing in this view</h3><p>Try another filter, or create a loan file.</p></div>
<p v-if="busy" class="empty-state" role="status">Loading files…</p>
</div>
</section>
<div v-if="creating" class="modal-backdrop" @click.self="creating=false"><section class="modal" v-focus-trap="()=>creating=false" role="dialog" aria-modal="true" aria-labelledby="create-title"><h2 id="create-title">Create a loan file</h2><p class="muted">After you create it, upload the bank statements or the appraisal.</p><form class="form-stack" @submit.prevent="create"><label>Loan file name<input v-model="form.name" required maxlength="150" placeholder="For example, Sample Street refinance"/></label><label>Your reference number (optional)<input v-model="form.reference" maxlength="80"/></label><label>Borrower already in this company<select v-model="form.borrower_id"><option value="">Choose a borrower</option><option v-for="b in borrowers" :value="b.id">{{b.name}}</option></select></label><label>Or type a new borrower name<input v-model="form.new_borrower" placeholder="Fictional borrower name" maxlength="120"/></label><label>What are you reviewing?<select v-model="form.module"><option value="bank">Bank statements</option><option value="appraisal">Appraisal</option><option value="dscr">Rental income</option></select></label><label class="check"><input type="checkbox" v-model="form.is_demo"/>This is a practice file with fictional documents</label><p class="micro">Do not upload a real borrower’s documents in a practice file.</p><p class="error" v-if="error">{{error}}</p><div class="actions"><button type="button" @click="creating=false">Cancel</button><button class="primary" :disabled="busy">Create file</button></div></form></section></div>
</template>
